// ===========================
// 制度の計算機 — 年金の繰上げ・繰下げの値の表（値・出典・確認日をセットで）
// どの値も下の SOURCES の原文（e-Gov 法令検索の国民年金法・厚生年金保険法と施行令、日本年金機構のページと早見表 PDF）を
// 2026-09-25 に読んで写した。率は法令で固定（令和4年4月から）なので、毎年変わるのは在職老齢年金の基準額（毎年度）と
// 老齢基礎年金の満額（毎年4月。画面の例に使うだけ）。
// 在職老齢年金の基準額 65 万円は制度の改定カレンダー（lib/kaitei-values.js の 2026-04-zairo）と同じ値（テストで一致を確かめる）。
// ブラウザでは window.KuriageValues、Node（テスト）では module.exports で使う
// ===========================
(function (root) {
  'use strict';

  var CHECKED = '2026-09-25';   // 下の出典を最後に原文で確かめた日
  var EGOV = 'https://laws.e-gov.go.jp/law/';
  var JPS = 'https://www.nenkin.go.jp/';
  var KK = JPS + 'service/jukyu/seido/roureinenkin/kuriage-kurisage/';

  var SOURCES = [
    { key: 'kuriage', label: '日本年金機構「年金の繰上げ受給」（更新 2024年8月19日）', url: KK + '20140421-01.html', where: '減額率 ＝ 0.4% × 繰上げ請求月から65歳に達する日の前月までの月数（最大24%）。昭和37年4月1日以前生まれは0.5%（最大30%）。老齢基礎年金と老齢厚生年金は原則として同時に繰上げ。請求した日の翌月分から支給。取消しできない。特別支給の老齢厚生年金を受けられる人の老齢厚生年金は、その受給開始年齢の前月までの月数で計算（一部繰上げ）' },
    { key: 'kurisage', label: '日本年金機構「年金の繰下げ受給」（更新 2026年8月12日）', url: KK + '20140421-02.html', where: '66歳以後75歳まで（昭和27年4月1日以前生まれ等は70歳まで）。増額率 ＝ 0.7% × 65歳に達した月から繰下げ申出月の前月までの月数（最大84%）。基礎と厚生は別々に繰下げできる。在職老齢年金で支給停止される額は増額の対象外（平均支給率 ＝ 月ごとの支給率の合計 ÷ 待機の月数、月の支給率 ＝ 1 −（在職支給停止額 ÷ 65歳時の老齢厚生年金額））。加給年金額・振替加算は増額の対象外で、待機中は受け取れない。70歳を過ぎてから65歳からの分をさかのぼって受け取ると、請求の5年前に繰下げの申出があったものとみなす（80歳以後などは除く）' },
    { key: 'hayamiKuriage', label: '日本年金機構「繰上げ減額率早見表」（昭和37年4月2日以降生まれ／4月1日以前生まれ）', url: KK + '20140421-01.files/hayami_S37.4iko.pdf', where: '60歳0か月 24.0%（0.5%の表は30.0%）〜64歳11か月 0.4%（0.5%）。年齢は請求時' },
    { key: 'hayamiKurisage', label: '日本年金機構「繰下げ増額率早見表」', url: KK + '20140421-02.files/hayamihyo.pdf', where: '66歳0か月 8.4% 〜 75歳0か月 84.0%' },
    { key: 'kokunenho', label: '国民年金法（e-Gov 法令検索）', url: EGOV + '334AC0000000141', where: '17条（年金額の1円未満の端数は50銭以上を切り上げ）、28条（66歳に達する前に請求していなければ繰下げの申出ができる。75歳に達した日後は75歳の日に申出があったものとみなす。申出の翌月から支給）、附則9条の2（繰上げ）' },
    { key: 'kokunenRei', label: '国民年金法施行令（令和8年4月1日施行版）', url: EGOV + '334CO0000000184', where: '4条の5（増額率 ＝ 千分の七 × 受給権を取得した月から申出の前月までの月数。百二十を超えるときは百二十）、12条（減額率 ＝ 千分の四 × 繰上げ請求月から65歳に達する日の属する月の前月までの月数）' },
    { key: 'kouneiho', label: '厚生年金保険法（e-Gov 法令検索）', url: EGOV + '329AC0000000115', where: '44条の3（受給権を取得した日から1年を経過した日前に請求していなければ繰下げの申出ができる。加算額は在職で停止される額を勘案。5年を経過した日後に請求して申出をしないときは請求の5年前に申出があったものとみなす）、46条（在職の支給停止。支給停止調整額62万円を賃金の変動で改定）、附則8条の2（特別支給の老齢厚生年金の受給開始年齢。男性は昭和36年4月1日以前生まれまで、女性は昭和41年4月1日以前生まれまで）' },
    { key: 'zairo', label: '日本年金機構「在職老齢年金の計算方法」（更新 2026年4月1日）・「在職老齢年金制度が改正されました」', url: JPS + 'service/jukyu/seido/roureinenkin/zaishoku/20150401-01.html', where: '令和8年度の支給停止調整額 65万円（令和8年3月までは51万円）。支給停止額（月）＝（基本月額 ＋ 総報酬月額相当額 − 65万円）÷ 2。基本月額は加給年金額を除いた老齢厚生年金（報酬比例部分）の月額、総報酬月額相当額は標準報酬月額 ＋ 直近1年の標準賞与額 ÷ 12。老齢基礎年金と経過的加算額は調整の対象外。例: 基本月額10万円・総報酬月額相当額46万円 → 改正前7.5万円、改正後10万円（全額支給）' },
    { key: 'r8gaku', label: '日本年金機構「令和8年4月分からの年金額等について」', url: JPS + 'oshirase/taisetu/kojin/2026/202604/0401.html', where: '老齢基礎年金（満額）月額70,608円（昭和31年4月2日以後生まれ。以前生まれは70,408円）。前年度から基礎年金1.9%、厚生年金（報酬比例部分）2.0%の引上げ' },
  ];

  // 特別支給の老齢厚生年金（報酬比例部分）の受給開始年齢（厚生年金保険法 附則8条の2。1号厚年・一般の人）
  // [この日以前に生まれた人, 開始年齢]。男性は1項、女性は2項（第1号厚生年金被保険者期間がある女性）
  var TOKUBETSU = {
    male: [['1955-04-01', 61], ['1957-04-01', 62], ['1959-04-01', 63], ['1961-04-01', 64]],   // 昭和28年4月2日〜は上の年齢から
    female: [['1960-04-01', 61], ['1962-04-01', 62], ['1964-04-01', 63], ['1966-04-01', 64]],
  };

  var V = {
    CHECKED: CHECKED,
    STALE_MONTHS: 12,             // 確認日からこの月数がたったら画面に注意を出す（在職老齢年金の基準額は毎年度改定）
    SOURCES: SOURCES,

    kurisageRate: 0.007,          // 繰下げ 1か月あたり（国年令4条の5）
    kurisageMin: 12,              // 66歳から（65歳に達した日から1年を経過した日前は申出できない）
    kurisageMax: 120,             // 75歳まで（120月）
    kurisageMaxOld: 60,           // 昭和27年4月1日以前生まれ（または平成29年3月31日以前に受給権）は70歳まで
    kurisageOldBornBy: '1952-04-01',
    kuriageRate: 0.004,           // 繰上げ 1か月あたり（国年令12条）
    kuriageRateOld: 0.005,        // 昭和37年4月1日以前生まれ
    kuriageOldBornBy: '1962-04-01',
    kuriageMax: 60,               // 60歳から

    zairo: { base: 650000, fiscalYear: '令和8年度', from: '2026-04', prevBase: 510000 },   // 支給停止調整額（毎年度改定）
    mangaku: { monthly: 70608, monthlyOld: 70408, fiscalYear: '令和8年度', oldBornBy: '1956-04-01' },   // 老齢基礎年金の満額（例に使うだけ）
    TOKUBETSU: TOKUBETSU,
    // 画面の比べる年齢の表
    COMPARE_AGES: [60, 62, 64, 65, 66, 68, 70, 72, 75],
    // 累計の表を出す年齢（この年齢に達した月まで）
    TOTAL_AGES: [70, 75, 80, 85, 90, 95, 100],
  };

  if (typeof module !== 'undefined' && module.exports) module.exports = V;
  else root.KuriageValues = V;
})(this);
